<template>
  <div class="talkAdventure">
    <div class="content1">
      <!-- <div class="title">拼手气红包</div> -->
      <van-popover
        v-model="showPopover"
        trigger="click"
        :actions="actions"
        @select="onSelect1"
      >
        <template #reference>
          <div class="title">{{ title }}<van-icon name="arrow-down" /></div>
        </template>
      </van-popover>
    </div>

    <van-form @submit="onSubmit">
      <van-field
        v-model="bagNum"
        name="红包个数"
        placeholder="填写红包个数"
        input-align="right"
        type="digit"
        autocomplete="off"
      >
        <div slot="label" style="display:flex">

          <div class="redBag" />
          <span class="filed-label">红包个数</span>
        </div>
        <template slot="button">个</template>
      </van-field>
      <div class="peopleNum">本群共{{ peopleNum }}人；余额:{{ remainingSum }}U</div>

      <van-field
        v-model="totalAmount"
        name="总金额"
        placeholder="$0.00"
        input-align="right"
        type="number"
        autocomplete="off"
      >
        <div slot="label" style="display:flex">
          <div class="usdt-icon" />
          <span class="filed-label">总金额</span>
        </div>
      </van-field>
      <van-swipe v-if="titleColor===0" class="my-swipe" :initial-swipe="initIndex" @change="changeParam">
        <van-swipe-item v-for="(item, index) in taskListZxh" :ref="'imageWrapper0'+index" :key="index">
          <div v-if="saveClick" class="taskCard1">
            <div class="wordstyle">{{ item.title }}</div>
          </div>
          <div v-else>
            <img class="taskCard" :src="item.medialink">
            <span v-if="!editable" class="imgWord">
              <span>{{ item.title }}</span>
            </span>
            <div v-if="editable"><textarea v-model="item.title" style="resize:none" class="imgWord" @change="changeImgWord" /></div>
          </div>
        </van-swipe-item>
      </van-swipe>
      <van-swipe v-if="titleColor===1" class="my-swipe" :initial-swipe="initIndex" @change="changeParam">
        <van-swipe-item v-for="(item, index) in taskListDmx" :ref="'imageWrapper1'+index" :key="index">
          <div v-if="saveClick" class="taskCard2">
            <div class="wordstyle">{{ item.title }}</div>
          </div>
          <div v-else>
            <img class="taskCard" :src="item.medialink">
            <span v-if="!editable" class="imgWord">
              <span>{{ item.title }}</span>
            </span>
            <div v-if="editable"><textarea v-model="item.title" style="resize:none" class="imgWord" @change="changeImgWord" /></div>
          </div>
        </van-swipe-item>
      </van-swipe>
      <div class="mark">
        <div>左右滑动选择任务卡片，抢到奖励金额</div>
        <div>最多的玩家接受惩罚</div>
      </div>
      <div class="content">
        <div v-for="(item,index) in titleList" :key="index" :class="titleColor === index?'title-click':'title'" @click="onChoose(index)">{{ item.title }}</div>
      </div>
      <div class="money"><div>{{ totalAmount || 0.00 }}</div>USDT</div>
      <div style="margin:auto;width:100%;dispaly:block">
        <van-button class="button" color="#F24530" size="normal" block type="info" native-type="submit" :disabled="!editable" @click="saveRedpack()">{{ buttonText }}</van-button>
      </div>
      <div class="tips">{{ tips }}</div>
    </van-form>

  </div>
</template>
<script>
// import TitleLine from '../modules/TitleLine'
import taskCard1 from '@/assets/tel/talk.jpg'
import taskCard2 from '@/assets/tel/adventure.jpg'
import html2canvas from 'html2canvas'
export default {
  components: {
    // TitleLine
  },
  data() {
    return {
      editable: true,
      buttonText: '塞钱进钱包',
      remainingSum: '0', // 余额
      showPopover: false,
      title: '任务红包',
      titleList: [{ title: '真心话' }, { title: '大冒险' }],
      bagNum: '',
      totalAmount: '',
      peopleNum: '12',
      money: '0.00',
      tips: '',
      actions: [{ text: '拼手气红包', type: '2' }, { text: '普通红包', type: '1' }, { text: '专属红包', type: '3' }, { text: '任务红包', type: '4' }],
      titleColor: 0,
      taskListZxh: [],
      taskListDmx: [],
      userid: null,
      chatid: null,
      params: { type: '4' },
      remark: '',
      medialink: '',
      initIndex: '0',
      currentPicIndex: 0,
      saveClick: false
    }
  },
  mounted() {
    if (this.$route.query.test) {
      const formData = new FormData()
      formData.append('initData', 'user=%7B%22id%22%3A6669226098%2C%22first_name%22%3A%22%E4%BB%B2%E6%98%8E%22%2C%22last_name%22%3A%22%E7%8E%8B%22%2C%22username%22%3A%22wangzhongming%22%2C%22language_code%22%3A%22zh-hans%22%2C%22allows_write_to_pm%22%3Atrue%7D&chat_instance=-594754764806165235&chat_type=supergroup&auth_date=1701666073&hash=767614987aca682c959542d539351ed7c7d6c95de45b2355a4444e428461d842')
      formData.append('hash', '767614987aca682c959542d539351ed7c7d6c95de45b2355a4444e428461d842')
      fetch(process.env.VUE_APP_BASE_API + '/yule/checkInitData', {
        method: 'POST',
        body: formData
      }).then(res => res.json())
        .then(data => {
          console.log(data)
          this.userid = data.userid
          this.chatid = data.chatid
          this.remainingSum = data.moneys
          this.peopleNum = data.membersize
          this.editable = data.diyright === 1
          if (!this.$route.query.type || this.$route.query.type === data.lastrecord.type) {
            this.titleColor = data.lastrecord.type === 4 ? 0 : 1
            this.remark = data.lastrecord.remark
            this.medialink = data.lastrecord.medialink
            this.totalAmount = data.lastrecord.moneys || ''
            this.bagNum = data.lastrecord.nums || ''
            this.params.type = data.lastrecord.type
          }
          // this.updateList(data.chatid)
          fetch(process.env.VUE_APP_BASE_API + '/yule/getTaskList' + '?suid=' + this.userid, {
            method: 'get'
          }).then(res => res.json())
            .then(data => {
              if (data.status == '1') {
                this.taskListZxh = data.datalist.filter(item => item.type === 1)
                this.taskListDmx = data.datalist.filter(item => item.type === 2)
                if (this.titleColor === 0) {
                  if (this.taskListZxh.find(ele => ele.title === this.remark)) {
                    this.initIndex = (this.taskListZxh.find(ele => ele.title === this.remark).nums) - 1
                    this.params.remark = this.taskListZxh[this.initIndex].title
                    this.params.medialink = this.taskListZxh[this.initIndex].medialink
                    this.currentPicIndex = this.initIndex
                  } else {
                    this.params.remark = this.taskListZxh[0].title
                    this.params.medialink = this.taskListZxh[0].medialink
                  }
                } else {
                  if (this.taskListDmx.find(ele => ele.title === this.remark)) {
                    this.initIndex = (this.taskListDmx.find(ele => ele.title === this.remark).nums) - 1
                    this.params.remark = this.taskListDmx[this.initIndex].title
                    this.params.medialink = this.taskListDmx[this.initIndex].medialink
                    this.currentPicIndex = this.initIndex
                  } else {
                    this.params.remark = this.taskListDmx[0].title
                    this.params.medialink = this.taskListDmx[0].medialink
                  }
                }
              } else {
                this.$toast(data.msg)
              }
            })
        })
    } else {
      const script = document.createElement('script')
      script.type = 'text/javascript'
      script.src = 'https://telegram.org/js/telegram-web-app.js?1'
      document.body.appendChild(script)
      script.onload = () => {
        const formData = new FormData()
        formData.append('initData', Telegram.WebApp.initData)
        formData.append('hash', Telegram.WebApp.initDataUnsafe.hash)
        fetch(process.env.VUE_APP_BASE_API + '/yule/checkInitData', {
          method: 'POST',
          body: formData
        }).then(res => res.json())
          .then(data => {
            console.log(data)
            this.userid = data.userid
            this.chatid = data.chatid
            this.remainingSum = data.moneys
            this.peopleNum = data.membersize
            this.editable = data.diyright === 1
            if (!this.$route.query.type || this.$route.query.type === data.lastrecord.type) {
              this.titleColor = data.lastrecord.type === 4 ? 0 : 1
              this.remark = data.lastrecord.remark
              this.medialink = data.lastrecord.medialink
              this.totalAmount = data.lastrecord.moneys || ''
              this.bagNum = data.lastrecord.nums || ''
              this.params.type = data.lastrecord.type
            }

            // this.updateList(data.chatid)
            fetch(process.env.VUE_APP_BASE_API + '/yule/getTaskList' + '?suid=' + this.userid, {
              method: 'get'
            }).then(res => res.json())
              .then(data => {
                if (data.status == '1') {
                  this.taskListZxh = data.datalist.filter(item => item.type === 1)
                  this.taskListDmx = data.datalist.filter(item => item.type === 2)
                  if (this.titleColor === 0) {
                    if (this.taskListZxh.find(ele => ele.title === this.remark)) {
                      this.initIndex = (this.taskListZxh.find(ele => ele.title === this.remark).nums) - 1
                      this.params.remark = this.taskListZxh[this.initIndex].title
                      this.params.medialink = this.taskListZxh[this.initIndex].medialink
                      this.currentPicIndex = this.initIndex
                    } else {
                      this.params.remark = this.taskListZxh[0].title
                      this.params.medialink = this.taskListZxh[0].medialink
                    }
                  } else {
                    if (this.taskListDmx.find(ele => ele.title === this.remark)) {
                      this.initIndex = (this.taskListDmx.find(ele => ele.title === this.remark).nums) - 1
                      this.params.remark = this.taskListDmx[this.initIndex].title
                      this.params.medialink = this.taskListDmx[this.initIndex].medialink
                      this.currentPicIndex = this.initIndex
                    } else {
                      this.params.remark = this.taskListDmx[0].title
                      this.params.medialink = this.taskListDmx[0].medialink
                    }
                  }
                } else {
                  this.$toast(data.msg)
                }
              })
          })
      }
    }
  },
  methods: {
    changeParam(val1, val2) {
      this.currentPicIndex = val1
      if (this.titleColor === 0) {
        this.params.type = '4'
        this.params.medialink = this.taskListZxh[val1].medialink
        this.params.remark = this.taskListZxh[val1].title
        // this.$nextTick(() => {
      } else if (this.titleColor === 1) {
        this.params.type = '5'
        this.params.medialink = this.taskListDmx[val1].medialink
        this.params.remark = this.taskListDmx[val1].title
        // html2canvas(this.$refs['imageWrapper0' + val1], {
        //   backgroundColor: null, // 解决生成会有白边的可能,但是没有遇到有白边,不知道有没有生效
        //   allowTaint: true, // 是否允许跨域图片(官方文档,代试验)
        //   useCORS: true,
        //   taintTest: true
        // })
        //   .then(canvas => {
        //     const dataURL = canvas.toDataURL('image/png')
        //     this.params.medialink = dataURL
        //   })
      }
    },
    changeImgWord(data) {
      if (this.titleColor === 0) {
        this.params.remark = data.currentTarget._value
      } else if (this.titleColor === 1) {
        this.params.remark = data.currentTarget._value
      }
    },
    // updateList(chatid) {
    //   fetch(process.env.VUE_APP_BASE_API + '/yule/getGroupUsers?chatid=' + chatid + '&suid=' + this.$route.query.suid + '&username=', {
    //     method: 'POST'
    //   }).then(res => res.json())
    //     .then(data => {
    //       this.peopleNum = data.size
    //     })
    // },
    async saveRedpack() {
      if (this.bagNum > this.peopleNum) {
        this.$toast('红包数量应不大于群人数！')
        return false
      }
      if (this.params.type === '3') {
        this.params.nums = '1'
        this.params.tobotid = this.$route.query.botid
      } else {
        this.params.nums = this.bagNum
        this.params.tobotid = ''
      }
      this.params.moneys = this.totalAmount
      // this.params.medialink = '' // 红包封面
      // this.params.remark = this.bless
      this.params.anonymous = this.isNameLess ? '1' : '0'
      this.params.gettype = 0
      // this.params.suid = this.$route.query.suid
      this.params.suid = this.userid
      this.params.chatid = this.chatid
      this.saveClick = true
      this.buttonText = '钱包提交中',
      this.editable = false
      await this.$nextTick()
      setTimeout(() => {
        html2canvas(document.getElementsByClassName('van-swipe-item')[this.currentPicIndex], {
          backgroundColor: null, // 解决生成会有白边的可能,但是没有遇到有白边,不知道有没有生效
          allowTaint: true, // 是否允许跨域图片(官方文档,代试验)
          useCORS: true,
          taintTest: true
        })
          .then(async(canvas) => {
            const dataURL = canvas.toDataURL('image/png')
            this.params.medialink = await this.uploadPic(dataURL)
            const paramString = '?type=' + this.params.type + '&nums=' + this.params.nums + '&tobotid=' + this.params.tobotid + '&moneys=' + this.params.moneys + '&medialink=' + this.params.medialink + '&remark=' + this.params.remark + '&anonymous=' + this.params.anonymous + '&gettype=' + this.params.gettype + '&suid=' + this.params.suid + '&chatid=' + this.params.chatid
            fetch(process.env.VUE_APP_BASE_API + '/yule/saveRedpack' + paramString, {
              method: 'POST'
            }).then(res => res.json())
              .then(data => {
                this.saveClick = false
                if (data.status == '1') {
                  this.$toast.success('发送成功')
                  this.buttonText = '塞钱进钱包',
                  this.editable = true
                  if (!this.$route.query.test) {
                    Telegram.WebApp.close()
                  }
                } else {
                  this.$toast(data.msg)
                }
              })
          })
      }, 3000)
    },
    btof(data, fileName) {
      const dataArr = data.split(',')
      const byteString = atob(dataArr[1])
      const options = {
        type: 'image/jpeg',
        endings: 'native'
      }
      const u8Arr = new Uint8Array(byteString.length)
      for (let i = 0; i < byteString.length; i++) {
        u8Arr[i] = byteString.charCodeAt(i)
      }
      return new File([u8Arr], fileName + '.jpg', options)
    },
    async uploadPic(base64) {
      const file = this.btof(base64, '合成.png')
      var formData = new FormData()
      formData.append('imgfile', file)
      return fetch(process.env.VUE_APP_BASE_API + '/yule/redpackimg', {
        method: 'POST',
        body: formData
      }).then(res => res.json())
        .then(data => {
          return data.imgsrc
          // this.uploader = [{ url: 'http://img.rr888.vip/img/yl-hbmrtb.png', deletable: false }, { url: data.imgsrc }]
          // this.clickPreview(file, data.imgsrc)
        })
    },
    onSelect1(action) {
      switch (action.type) {
        case '2':
          this.$router.push({ path: '/sendBag', query: { type: action.type, test: '1' }})
          // this.totalAmountName = '总金额'
          // this.showBagNum = true
          break
        case '1':
          this.$router.push({ path: '/sendBag', query: { type: action.type, test: '1' }})
          // this.totalAmountName = '单个金额'
          // this.showBagNum = true
          break
        case '3':
          this.$router.push({ path: '/sendBag', query: { type: action.type, test: '1' }})
          // this.totalAmountName = '金额'
          // this.showBagNum = false
          break
        case '4':
          break
      }
    },
    onChoose(id) {
      this.titleColor = id
      this.params.type = id === 0 ? '4' : '5'
    },
    onSubmit() {
    }
  }

}
</script>
